#!/usr/bin/env python3
import json
import os
from collections import defaultdict

# Initialize data structures
user_data = defaultdict(lambda: {"total_amount": 0.0, "total_items": 0})
tag_counts = defaultdict(int)

# Process all JSONL files
for filename in sorted(os.listdir('/app')):
    if filename.endswith('.jsonl'):
        filepath = os.path.join('/app', filename)
        with open(filepath, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                record = json.loads(line)
                user = record['user']
                amount = record['amount']
                items = record['items']
                tags = record.get('tags', [])

                # Aggregate user data
                user_data[user]['total_amount'] += amount
                user_data[user]['total_items'] += items

                # Count tags
                for tag in tags:
                    tag_counts[tag] += 1

# Get top 5 users by amount (sorted by total_amount descending)
sorted_users = sorted(user_data.items(), key=lambda x: x[1]['total_amount'], reverse=True)
top_5_users = {}
for user, data in sorted_users[:5]:
    top_5_users[user] = {
        "total_amount": round(data['total_amount'], 2),
        "total_items": data['total_items']
    }

# Get top 5 tags by count (sorted by count descending)
sorted_tags = sorted(tag_counts.items(), key=lambda x: x[1], reverse=True)
top_5_tags = {}
for tag, count in sorted_tags[:5]:
    top_5_tags[tag] = {"count": count}

# Create output structure
output = {
    "top_5_users_by_amount": top_5_users,
    "top_5_tags_by_count": top_5_tags
}

# Write to file
with open('/app/aggregates.json', 'w') as f:
    json.dump(output, f, indent=2)

print("Done! Output written to /app/aggregates.json")
print(f"Processed {len(user_data)} unique users, {len(tag_counts)} unique tags")
